function toast(s){if(!s)return;const el=$('toast');el.textContent=String(s);el.hidden=false;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('show');el.hidden=true;el.textContent='';},2600);}
