function tone(f=500,d=.08,type='sine',vol=.035){if(!sound)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d);}catch{}}
function save(){if(!S.player)return;refillGM(S.player);if(mode==='game')updateHUD();S.player.buffs=S.player.buffs.filter(b=>b.until>Date.now());try{let rows=[];try{rows=JSON.parse(localStorage.getItem('elyndra-ranks-06')||'[]');}catch{}localStorage.setItem('elyndra-ranks-06',JSON.stringify(recordHero(Array.isArray(rows)?rows:[],S.player,stats(S.player).pc)));localStorage.setItem(KEY,JSON.stringify(S.player));if(S.player.localRole==='gm'){let roster=[];try{roster=JSON.parse(localStorage.getItem('elyndra-gm-characters')||'[]');}catch{}localStorage.setItem('elyndra-gm-characters',JSON.stringify(updateGMRoster(Array.isArray(roster)?roster:[],S.player)));}localStorage.setItem(S.player.testMode?'elyndra-lab-04':'elyndra-campaign-04',JSON.stringify(S.player));$('saveState').textContent='PROGRESSO SALVO';}catch{$('saveState').textContent='NÃO FOI POSSÍVEL SALVAR';}}
function fx(type,x,y,extra={}){S.effects.push({type,x,y,life:extra.life||.9,max:extra.life||.9,...extra})}
function ring(x,y,color){fx('ring',x,y,{color,life:.65})}
