function spawn(x,y,type='wolf',level=1,boss=false){if(blocked(x,y,S.player?.zone||'coast')){let found=false;for(let radius=1;radius<=7&&!found;radius++)for(const [dx,dy] of [[radius,0],[-radius,0],[0,radius],[0,-radius],[radius,radius],[-radius,-radius]])if(!blocked(x+dx,y+dy,S.player?.zone||'coast')){x+=dx;y+=dy;found=true;break;}}const test=S.player?.testMode,st=test?stats(S.player):null,budget=enemyBudget(level,boss);const maxHp=budget.hp,theme=MOB_THEMES[S.player?.region||0];const e={id:Math.random().toString(36),x,y,homeX:x,homeY:y,type,level,boss,name:boss?'Guardião de '+(CONTENT?.regions[S.player?.region||0]?.name||'Lúmen'):type==='wisp'?theme.spirit:theme.name,archetype:boss?'construct':type==='wisp'?'spirit':theme.kind,theme:S.player?.region||0,hp:maxHp,maxHp,def:budget.defense,atk:budget.attack,speed:boss?1.8:2.05,stun:0,cooldown:1+Math.random(),winding:0,deadTimer:0,respawn:0,moving:false};if(boss)e.shield=maxHp*.10;S.enemies.push(e);return e;}
function populate(){S.combatEpoch=(S.combatEpoch||0)+1;S.cast=null;S.actionLock=0;setWorldRegion(S.player?.region||0);S.bossEncounter=null;S.enemies=[];S.pendingHits=[];S.target=null;S.attack=false;S.goal=null;S.loot=[];S.decor=decorations(S.player?.zone||'coast');if(S.player?.visualSlice&&S.player?.zone==='coast'){populateGarden();return;}if(S.player?.zone==='dungeon'){S.dungeonWave=0;S.dungeonWon=false;nextWave();}else{for(const [x,y,l] of [[18,23,1],[21,24,1],[23,21,2],[20,28,2],[26,26,2],[17,30,2],[25,17,2],[29,20,3]])spawn(x,y,'wolf',Math.max(CONTENT?.regions[S.player.region]?.range[0]||1,Math.min(CONTENT?.regions[S.player.region]?.range[1]||24,S.player.level+l-1)));for(const [x,y] of [[24,11],[27,13],[22,8]])spawn(x,y,'wisp',Math.max(CONTENT?.regions[S.player.region]?.range[0]||1,Math.min(CONTENT?.regions[S.player.region]?.range[1]||24,S.player.level+1)));}}
function nextWave(){const waveLevel=S.dgData?.level_min||3;S.dungeonWave++;if(S.dungeonWave<=2){announce('ONDA '+S.dungeonWave+' / 3');for(let i=0;i<3;i++)spawn(15+i*3,16+Math.random()*3,S.dungeonWave===2?'wisp':'wolf',waveLevel);}else if(S.dungeonWave===3){const guardian=spawn(22,18,'guardian',waveLevel,true);guardian.name=S.dgData?.boss||'Sentinela do Farol';announce('O GUARDIÃO DESPERTOU');}else{S.dungeonWon=true;const p=S.player;p.dungeonClears++;addMaterials(p,{'Fragmento de Magícula':15,'Cristal de Vínculo':10,'Essência de Montaria':10});const reward=dungeonReward(p,S.dgData);p.shards+=S.dgData?.players===5?3:1;gainXP(reward.xp);const drop=campaignDrop(p,S.dgData?.equipment_level||p.level);if(p.bag.length<80)p.bag.push(drop);announce('MASMORRA CONCLUÍDA');toast('+'+reward.gold+' ouro · +'+reward.xp+'XP · '+drop.name);p.regionClears[p.region||0]=(p.regionClears[p.region||0]||0)+1;chapterProgress(p,{type:'dungeon',region:p.region||0});addMaterials(p,{'Pluma Astral':2+(S.dgData?.players||1),'Essência de Aura':3+(S.dgData?.players||1)});if(p.quest===3)p.quest=4;save();}}
function start(p){if(GM_BUILD&&!CONTENT){toast('Carregando catálogo de testes…');contentReady.then(()=>{if(CONTENT)start(p);});return;}if(GM_BUILD){provisionGM(p,CONTENT);document.body.dataset.gm='true';}initChapters(p);initAscension(p);initCompanions(p);if(p.testMode&&!p.systems11){p.companions.owned.slime||={rank:1};p.companions.owned.wolf||={rank:1};p.companions.pet||='slime';p.companions.mount||='wolf';p.magicula.rank=Math.max(1,p.magicula.rank);for(const m of ['Cristal de Vínculo','Essência de Montaria','Fragmento de Magícula'])p.materials[m]=(p.materials[m]||0)+50000;p.systems11=true;}migrateTwoHanded(p);p.visualSlice=false;S.pendingHits=[];S.dgData=null;S.bossEncounter=null;p.attributes||={for:0,int:0,des:0};p.materials||={};if(!p.progressionVersion){p.gold=Math.max(p.gold,5000);p.shards=Math.max(p.shards,10);addMaterials(p,{L01:40,E01:10,N01:2,K01:10,P01:10});p.progressionVersion=4;}p.bar||=[0,1,2,3];p.passive||=PASSIVE_OPTIONS[p.classId][0][2];p.region||=0;p.energy??=100;p.resource??=0;S.skillCD={};S.timers={};S.shield=0;S.guard=false;S.player=p;S.pressureStartedAt=-100;S.pressureReadyAt=0;S.comboCount=0;S.lastComboHit=-10;S.inventoryState={filter:"all",scroll:0};document.body.dataset.visual='helios';if(p.visualSlice){p.zone='coast';p.region=0;}for(const slot of ['head','hands','legs','boots'])if(!(slot in p.equipped)){const piece=item(p.classId,1,slot);p.bag.push(piece);p.equipped[slot]=piece.id;}const st=stats(p);p.hp=clamp(p.hp||st.hp,1,st.hp);p.mp=clamp(p.mp??st.mp,0,st.mp);if(p.zone==='dungeon'){p.zone='coast';p.x=27;p.y=11;}S.cd={s1:0,s2:0,def:0,hp:0,mp:0,basic:0};S.buffShield=0;S.eye=0;S.pulses=[];populate();mode='game';document.body.dataset.playing='true';document.body.dataset.class=p.classId;$('welcome').hidden=true;$('creation').hidden=true;$('hud').hidden=false;$('heroName').textContent=p.name;$('avatar').textContent=CLASSES[p.classId].icon;for(const [id,key] of [['bagButton','bag'],['forgeButton','forge'],['spellbookButton','skills'],['atlasQuick','map']])$(id).querySelector('span').innerHTML=commandIcon(key);$('rankButton').innerHTML=commandIcon('ranking');$('menuButton').innerHTML=commandIcon('settings');const c=CLASSES[p.classId];$('attack').querySelector('span').innerHTML=commandIcon(p.classId==='ARC'?'aura':'skills');for(const [id,key] of [['skill1','skill1'],['skill2','skill2'],['defense','defense']]){$(id).querySelector('small').textContent=c[key].name;$(id).querySelector('span').textContent=c[key].icon||'⛨';$(id).setAttribute('aria-label',c[key].name);}S.nav=false;updateSkillLabels();r.cam={x:p.x,y:p.y};save();updateHUD();toast(p.localRole==='gm'?'GM ativo: build completa e recursos livres. Console GM no menu.':p.testMode?'Laboratório250. Para ganhar níveis, escolha Campanha na tela inicial.':'Toque na missão para ir ao objetivo. Itens e Evoluir ficam na barra inferior.');}
