function selectClass(id){document.body.dataset.class=id;selectedClass=id;const c=CLASSES[id];document.querySelectorAll('[data-class]').forEach(b=>{b.classList.toggle('selected',b.dataset.class===id);b.setAttribute('aria-pressed',String(b.dataset.class===id));});$('chosenRole').textContent=c.role;$('chosenName').textContent=c.name;$('chosenDesc').textContent=c.desc;$('chosenSkills').innerHTML=[KITS[id][0].name,KITS[id][1].name,KITS[id][5].name].map(v=>'<span>'+v+'</span>').join('');animatedPortrait($('classPreview'),id);}
