$('enterButton').onclick=enterElyndra;$('enterLabButton').onclick=()=>{showModal('Laboratório de testes','ATALHO · NÃO É PROGRESSÃO DE CAMPANHA','<p>Este modo coloca o personagem no250, libera todos os mapas e concede recursos de teste. Ele não participa do ranking. Para evoluir normalmente, escolhaIniciar campanha.</p><button class="primary" id="confirmLabCreation">ENTRAR NO TESTE NV250</button>');$('confirmLabCreation').onclick=()=>{closeModal();const p=createPlayer(selectedClass,$('nameInput').value);initAscension(p);p.level=250;p.testMode=true;p.gold=50000000;p.shards=5000;p.runes=500;p.wallet.cash=100000;addMaterials(p,{'Pluma Astral':100000,'Essência de Aura':100000,'Núcleo de Cataclismo':500});start(p);if(CONTENT)giveReferenceSet();};};
function showModal(title,sub,html){portraitPreview=null;if(!html||!String(html).trim())return;$('modalTitle').textContent=title;$('modalSub').textContent=sub;$('modalBody').innerHTML=html;$('modalBody').scrollTop=0;$('modal').querySelector('.modal').dataset.theme=/Empório|suprimento/.test(title)?'shop':/Forja|Fabricar|aprimoramento/.test(title)?'forge':/Magícula|Aura|Asas/.test(title)?'cosmic':'default';$('modal').querySelector('.modal').dataset.panel=html.includes('commandDeck')?'menu':html.includes('inventoryLayout')?'inventory':html.includes('itemSheet')?'item':html.includes('ascensionLayout')?'ascension':'standard';const frame=$('modal').querySelector('.modal');frame.classList.remove('panelEnter');void frame.offsetWidth;frame.classList.add('panelEnter');$('modal').hidden=false;$('closeModal').focus({preventScroll:true});S.attack=false;keys.clear();joy.x=joy.y=0;S.nav=false;S.goal=null;$('stick').style.transform='';}
function closeModal(){$('modal').hidden=true;portraitPreview=null;save();$('bagButton')?.focus({preventScroll:true});}
$('closeModal').onclick=closeModal;$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});
function isCombat(){return !S.player?.testMode&&S.time-S.lastCombat<10;}
function talk(){const p=S.player;if(!p)return;if(p.quest>=4){journal();return;}if(p.quest===0){showModal('O último farol','ILYRA · GUARDIÃ DO FAROL','<p>“Toda noite, esta luz guiava os navios de volta. Ontem ela piscou três vezes… e a névoa respondeu.”</p><p>Os lobos da costa estão inquietos. Derrote <b>5 lobos das falésias</b> e volte até mim. Depois, investigaremos a cripta.</p><div class="notice">Recompensa: 80 ouro · 70 EXP · 3 poções de HP · 2 cristais.<br>Primeiro objetivo recomendado para aprender seu personagem.</div><button class="primary" id="acceptQuest">ACEITAR MISSÃO <span>→</span></button>');$('acceptQuest').onclick=()=>{p.quest=1;p.kills=0;closeModal();toast('Missão aceita. Os lobos ficam a sudeste, após a estrada.');S.track=true;};}
else if(p.quest===1){showModal('A costa está inquieta','ILYRA · MISSÃO EM ANDAMENTO',`<p>“Ainda ouço os uivos na estrada. Tome cuidado com os ataques anunciados.”</p><div class="progressrow"><span>Lobos derrotados</span><b>${p.kills} / 5</b></div><p>Vigia: selecione o alvo, ative o ataque básico e mantenha distância. Bastião: aproxime-se, interrompa com o escudo e use Baluarte.</p>`);}
else if(p.quest===2){showModal('Uma passagem esquecida','ILYRA · RECOMPENSA DISPONÍVEL','<p>“Você trouxe um pouco de paz à costa. Mas a origem do chamado está na <b>Cripta do Farol</b>.”</p><p>O portal fica entre as ruínas a nordeste. Seu sentinela protege uma relíquia antiga.</p><button class="primary" id="claimQuest">RECEBER E INVESTIGAR A CRIPTA →</button>');$('claimQuest').onclick=()=>{p.gold+=80;p.shards+=2;p.pots.hp+=3;gainXP(70);p.quest=3;closeModal();announce('JORNADA ATUALIZADA');toast('+80 ouro · +70 EXP · +3 poções · +2 cristais');};}
else if(p.quest===3){showModal('Além da névoa','ILYRA · SEGUNDA ETAPA','<p>O portal da Cripta do Farol está a nordeste. São três ondas; a última revela o sentinela. Leve poções e aprimore sua arma.</p><div class="notice">Esta é uma masmorra solo do protótipo. Grupos online e os chefes do projeto completo ainda não estão disponíveis.</div>');}
else {showModal('A luz voltou a respirar','ILYRA · CAPÍTULO CONCLUÍDO','<p>“O sentinela despertou porque as relíquias estão se movendo. Você encontrou o primeiro sinal de algo muito maior.”</p><p>O capítulo inicial está concluído. Continue evoluindo nos contratos de caça, masmorras e regiões do Atlas. Abra Mapa na barra inferior para viajar.</p><div class="notice">Abra Mapa para viajar pelas regiões liberadas por nível e entrar nas masmorras. Grupos e guerras online ainda não estão disponíveis.</div>');}}
function dungeonEntry(){const p=S.player;if(p.zone==='dungeon'){exitDungeon();return;}if((p.region||0)>0){atlas();return;}showModal('Cripta do Farol','MASMORRA SOLO · PRIMEIRO PROTÓTIPO',`<p>Uma entrada esquecida sob as pedras do farol. Duas ondas protegem o <b>Sentinela do Farol</b>.</p><div class="stats"><div class="stat">Grupo <b>1 jogador</b></div><div class="stat">Nível recomendado <b>3+</b></div><div class="stat">Poder recomendado <b>2.000</b></div><div class="stat">Seu poder <b>${stats(p).pc.toLocaleString('pt-BR')}</b></div></div><p>Recompensa: 120 ouro, 90 EXP, 4 cristais e um equipamento C com uma opção aleatória. Você pode sair a qualquer momento pelo menu.</p><div class="notice">Níveis e ritmo de XP foram acelerados para testar o combate. Esta DG de teste ainda não é a progressão final do blueprint.</div><button class="primary" id="enterDungeon">ENTRAR NA MASMORRA →</button>`);$('enterDungeon').onclick=()=>{p.zone='dungeon';p.x=11;p.y=12;const st=stats(p);p.hp=st.hp;p.mp=st.mp;closeModal();S.lastCombat=S.time-10;populate();announce('CRIPTA DO FAROL');save();};}
function exitDungeon(){const p=S.player;S.dgData=null;S.bossEncounter=null;p.zone='coast';p.x=27;p.y=11;S.pulses=[];populate();const st=stats(p);p.hp=Math.max(p.hp,st.hp*.5);closeModal();announce(CONTENT?.regions[p.region||0]?.name||'PORTO DE LÚMEN');save();}
function interact(){if(mode!=='game'||!$('modal').hidden)return;if(S.near?.startsWith('npc'))interactNpc(Number(S.near.slice(3)||0));else if(S.near==='portal')dungeonEntry();else toast('Aproxime-se de Ilyra ou do portal para interagir.');}
