function gainXP(amount){const p=S.player,levels=advanceXP(p,amount);if(levels){const st=stats(p);p.hp=st.hp;p.mp=st.mp;ring(p.x,p.y,'#e9d49a');fx('ascend',p.x,p.y,{life:1.5,color:'#ffe7a3'});showMilestone('NÍVEL '+p.level,'+'+(levels*5)+' pontos disponíveis · novo potencial','attributes',attributesPanel);p.gold+=levels*500;p.shards+=levels;S.levelPulse=1.5;tone(880,.4);save();}return levels;}
