attackButton.onclick=e=>{if(e.detail===0){attackStart();setTimeout(attackStop,180);}};

function usePotion(type){if(mode!=='game'||!$('modal').hidden)return;const p=S.player,st=stats(p);if(S.cd[type]>0){toast('Poção em recarga: '+Math.ceil(S.cd[type])+'s.');return;}if(p.pots[type]<=0){toast('Sem poções. Visite a loja.');return;}if(p[type]>=st[type]){toast(type.toUpperCase()+' já está cheio.');return;}p.pots[type]--;S.cd[type]=20;S.pulses.push({type,maxAtUse:st[type],rate:type==='hp'?.15:.20,left:5,timer:0});toast('Recuperando '+type.toUpperCase()+' em 5 pulsos.');tone(type==='hp'?520:660,.15);save();}
$('hpPotion').onclick=()=>usePotion('hp');$('mpPotion').onclick=()=>usePotion('mp');
function statGrid(){const p=S.player,st=stats(p);return '<p class="classFocus"><b>'+CLASS_PROFILES[p.classId].primary+'</b> · '+CLASS_PROFILES[p.classId].focus+'</p><div class="stats">'+[['Magículas',magiculaAmount(st.pc,p.magicula?.rank||0).toLocaleString('pt-BR')+' μ'],['Núcleo de Magículas',(p.magicula?.rank||0)+'/100'],['Pet ativo',COMPANIONS.find(d=>d.id===p.companions?.pet)?.name||'Nenhum'],['Montaria ativa',COMPANIONS.find(d=>d.id===p.companions?.mount)?.name||'Nenhuma'],['Poder total',st.pc.toLocaleString('pt-BR')],['Poder ofensivo',st.offensePower.toLocaleString('pt-BR')],['Poder defensivo',st.defensePower.toLocaleString('pt-BR')],['Intervalo do ataque',basicInterval(st,{haste:S.hasteBuff>0,dance:S.timers.dance>0}).toFixed(3)+'s'],['Golpes por segundo',(1/basicInterval(st,{haste:S.hasteBuff>0,dance:S.timers.dance>0})).toFixed(2)],['Ataque físico',st.af],['Ataque mágico',st.am],['Defesa',st.def],['HP máximo',st.hp],['MP máximo',st.mp],['Taxa crítica',(st.crit*100).toFixed(1)+'%'],['Limite crítico',(st.maxcrit*100).toFixed(1)+'%'],['Taxa excedente',(Math.max(0,st.critRaw-st.maxcrit)*100).toFixed(1)+'%'],['Dano crítico adicional',((st.critd-1)*100).toFixed(1)+'%'],['Ampliação de espada',(st.ampF*100).toFixed(1)+'%'],['Ampliação de magia',(st.ampM*100).toFixed(1)+'%'],['Penetração física',Math.round(st.penF)],['Penetração mágica',Math.round(st.penM)],['Precisão',Math.round(st.acc)],['Evasão',Math.round(st.evasion)],['Velocidade de ataque','+'+(st.haste*100).toFixed(1)+'%'],['Resistência à taxa crítica',(st.critres*100).toFixed(1)+'%'],['Resistência ao dano crítico',(st.critdres*100).toFixed(1)+'%'],['Resistência à ampliação',(st.ampres*100).toFixed(1)+'%'],['Tenacidade',(st.ten*100).toFixed(1)+'%'],['Dano PvP',(st.pvp*100).toFixed(1)+'%'],['Redução de dano',Math.round(st.dr)],['Redução de recarga',(st.cdr*100).toFixed(1)+'%']].map(v=>`<div class="stat">${v[0]}<b>${v[1]}</b></div>`).join('')+'</div><p class="subtle">Crítico inicial5%, limite50%, dano crítico adicional20%. O limite vem antes das resistências. Escala de poder v2:2× (ofensivo + defensivo). É uma pontuação, não o dano de um golpe. O poder estima dano útil e sobrevivência contra referência do seu nível; excedentes de crítico e amplificação errada não inflam o ranking.</p>';}

