function collection(){const p=S.player;showModal('Coleção de equipamentos','PRÉVIA VISUAL · NÍVEIS175–250',`<p>Selecione uma família para ampliar a aparência da sua classe. Famílias disponíveis no catálogo e na criação. ULTRA exige nível250.</p><div class="collectionTabs">${[['SS+','Vanguarda',175],['SSS','Soberano',195],['SSS+','Transcendente',215],['ULTRA','Primordial',250]].map(([q,n,l])=>`<button class="smallbtn" data-quality="${q}" data-req="${l}" data-title="${n}">${q}<small>${n}</small></button>`).join('')}</div><div class="collectionViewer"><canvas id="collectionPreview" width="400" height="380" aria-label="Prévia da coleção selecionada"></canvas><div><h3 id="collectionName">Primordial +25</h3><p id="collectionInfo">Criação apenas no250. Prévia com assinatura de encantamento.</p><p>Armas da classe, ornamentos de armadura e efeitos em torno da arma. Sem aumentar atributos do personagem nesta tela.</p></div></div><button class="textlink" id="collectionBack">← Voltar ao personagem</button>`);const draw=(q,title,req)=>{$('collectionName').textContent=title+' +25';$('collectionInfo').textContent='Nível'+req+' · '+(q==='ULTRA'?'Somente criação250':'Família '+q)+' · mostruário de aparência';animatedPortrait($('collectionPreview'),p.classId,{quality:q,enchant:25});};document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>draw(b.dataset.quality,b.dataset.title,b.dataset.req));draw('ULTRA','Primordial',250);$('collectionBack').onclick=inventory;}
function shop(){const p=S.player;showModal('Boticária de Lúmen','MIRA · LOJA COM OURO',`<div class="notice">Saldo: ${p.gold} ouro. Recuperação fácil de obter; elixires são opcionais, com duração de10min e bônus que respeitam os tetos.</div><h3>Recuperação</h3><div class="itemrow"><div class="itemicon">⚗</div><div class="itemdata"><strong>Poção de HP menor ×3</strong><p>15%HP máximo em5s. Recarga20s.</p></div><button data-buy="hp">15 ◈</button></div><div class="itemrow"><div class="itemicon">⚗</div><div class="itemdata"><strong>Poção de MP menor ×3</strong><p>20%MP máximo em5s. Recarga20s.</p></div><button data-buy="mp">12 ◈</button></div><h3>Elixires · 10 minutos</h3>`+[['crit','Mira','+3 pontos de chance crítica'],['critd','Fúria','+5 pontos de dano crítico'],['hp','Vitalidade','+5% HP máximo, sem curar'],['def','Fortaleza','+5% defesa']].map(([k,n,d])=>`<div class="itemrow"><div class="itemdata"><strong>Elixir de ${n}</strong><p>${d}. ${k==='crit'||k==='critd'?'Família ofensiva':'Família defensiva'}.</p></div><button data-buff="${k}">60 ◈ · usar</button></div>`).join('')+'<p class="notice">Economia reduzida para teste. Um buff por família, sem acumular duração. Tempo continua offline. Loja cash e pagamentos não estão implementados nesta alpha.</p>');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const cost=b.dataset.buy==='hp'?15:12;if(p.gold<cost){toast('Ouro insuficiente.');return;}p.gold-=cost;p.pots[b.dataset.buy]+=3;save();shop();toast('3 poções adicionadas.');});document.querySelectorAll('[data-buff]').forEach(b=>b.onclick=()=>{const type=b.dataset.buff,family=['crit','critd'].includes(type)?'offensive':'defensive';if(p.gold<60){toast('Ouro insuficiente.');return;}const active=p.buffs.find(v=>v.family===family&&v.until>Date.now());if(active&&Date.now()-active.started<60000){toast('Aguarde60s entre elixires da mesma família.');return;}p.gold-=60;p.buffs=p.buffs.filter(v=>v.family!==family);p.buffs.push({type,family,started:Date.now(),until:Date.now()+600000});p.hp=Math.min(p.hp,stats(p).hp);save();shop();toast('Elixir ativo por10min.');});}
