function journal(){const p=S.player;if(!CONTENT)return;const q=chapterObjective(p),reward=chapterReward(p,CONTENT.regions);showModal('Jornada de Elyndra','CAPÍTULO '+((p.region||0)+1)+' · '+CONTENT.regions[p.region||0].name.toUpperCase(),`<div class="chapterHero"><small>O CHAMADO DAS RELÍQUIAS</small><h3>${q.title}</h3><p>${q.definition.story}</p><b>Contato: ${q.definition.npc}</b></div>${p.quest<4?'<p class="notice">Primeiro, conclua a missão de Ilyra e a Cripta do Farol. Este capítulo se abre após a introdução.</p>':''}<div class="chapterSteps">${['Investigar '+q.definition.landmark,'Recuperar '+q.definition.collectible,'Concluir uma masmorra da região','Estabilizar o selo com Ilyra'].map((text,i)=>`<div class="chapterStep ${q.state.stage>i?'done':q.state.stage===i?'current':''}"><b>${q.state.stage>i?'✓':i+1}</b><span>${text}<small>${i===1?(q.state.kills||0)+' / '+q.definition.target:q.state.stage>i?'Concluído':q.state.stage===i?'Objetivo atual':'Próxima etapa'}</small></span></div>`).join('')}</div><div class="questRewards"><b>Recompensa única do capítulo</b><span>${reward.gold.toLocaleString('pt-BR')} ouro · ${reward.xp.toLocaleString('pt-BR')} EXP<br>${reward.plumes} plumas · ${reward.essences} essências de aura</span></div><div class="actions"><button class="primary" id="trackChapter">${p.quest<4?'SEGUIR INTRODUÇÃO':q.state.stage===4?'ABRIR MAPA':'IR AO OBJETIVO'}</button>${q.state.stage===3?'<button class="primary" id="claimChapter">RECEBER RECOMPENSA</button>':''}</div><p class="subtle">As amostras são registradas no objetivo, sem ocupar a mochila. Combate e entrada na masmorra são manuais. ${p.testMode?'Laboratório não recebe recompensas de campanha.':''}</p><details><summary>Os 12 capítulos</summary>${CHAPTERS.map((d,i)=>`<div class="progressrow"><span>${i+1}. ${d.title}<small>${CONTENT.regions[i].name} · Nv${CONTENT.regions[i].range[0]}+</small></span><b>${chapterState(p,i).stage===4?'✓':'○'}</b></div>`).join('')}</details>`);$('trackChapter').onclick=()=>{closeModal();if(q.state.stage===4&&p.quest>=4)atlas();else navigateQuest();};if($('claimChapter'))$('claimChapter').onclick=()=>{const out=claimChapter(p,CONTENT.regions);if(!out.ok){toast(out.reason);return;}gainXP(out.reward.xp);save();journal();showMilestone('SELO ESTABILIZADO',out.reward.gold.toLocaleString('pt-BR')+' ouro · '+out.reward.xp.toLocaleString('pt-BR')+' EXP','quest',journal);};}

function navigateQuest(){if(!S.player||mode!=='game')return;const p=S.player;S.attack=false;S.track=true;if(S.nav){S.nav=false;S.goal=null;toast('Caminho cancelado.');return;}if(p.zone==='dungeon'){toast('Conclua a cripta. O combate é manual.');return;}const dest=p.quest>=4?chapterObjective(p).goal:(p.quest===1)?{x:21,y:23}:p.quest===3?{x:27,y:10.5}:{x:12,y:13.5};S.goal=dest;S.nav=true;toast('Indo ao objetivo. Mover o joystick cancela o caminho.');}
