function campaignDrop(p,level){if(!CONTENT)return item(p.classId,Math.min(level,p.level),'weapon','D');const eligible=CONTENT.items.filter(i=>i.class_id===p.classId&&i.level_min<=level&&!['SSS','SSS+','ULTRA'].includes(i.rarity)),best=Math.max(...eligible.map(i=>i.level_min),1),pool=eligible.filter(i=>i.level_min===best);return pool.length?convertItem(pool[Math.floor(Math.random()*pool.length)]):item(p.classId,1);}
const SLOTS=['head','neck','armor','hands','weapon','secondary','legs','boots','ring1','ring2'];
function itemName(i){return safe(i.name)+(i.enchant?' +'+i.enchant:'');}
