function populateGarden(){
 const p=S.player;S.decor=[...[ [10,19],[12,26],[17,13],[25,15],[29,24],[23,29],[9,24],[29,19] ].map(([x,y],n)=>({x,y,kind:'tree',seed:n+100})),{x:18,y:15,kind:'ruin',seed:80},{x:27,y:23,kind:'ruin',seed:81},{x:14,y:23,kind:'lamp',seed:82},{x:25,y:26,kind:'lamp',seed:83}];
 for(const [x,y] of [[20,22],[23,25],[18,27],[26,21]]){const wolf=spawn(x,y,'wolf',175);wolf.name='Lobo da Guarda Solar';wolf.archetype='wolf';wolf.speed=1.6;}
 if(p.sliceKills>=3&&!p.sliceWon){const b=spawn(23,22,'wolf',175);b.boss=true;b.gardenBoss=true;b.archetype='wolf';b.name='Fenrir, Guardião de Hélion';b.maxHp=b.hp=enemyBudget(175).hp*1.8;}
}
async function startVisualGarden(){
 const button=$('visualStart');button.disabled=true;button.textContent='CARREGANDO ARTE…';const ready=await visualAssetsReady;button.disabled=false;button.textContent='JOGAR NOVA ÁREA GRÁFICA →';
 if(!ready){showModal('Não foi possível carregar a arte','CONEXÃO DOS RECURSOS','<p>Um recurso visual não carregou. Recarregue a página e tente novamente. Sua campanha foi preservada.</p>');return;}
 if(!CONTENT){toast('O catálogo ainda está carregando. Tente novamente em instantes.');return;}const p=createPlayer(selectedClass,'Guardião');initAscension(p);p.level=175;p.testMode=true;p.visualSlice=true;p.x=18;p.y=22;p.region=0;p.gold=5000000;p.shards=500;p.runes=100;p.wallet.cash=100000;p.attributes=p.classId==='ARC'?{for:50,int:750,des:70}:p.classId==='VIG'||p.classId==='ESP'?{for:200,int:0,des:670}:p.classId==='LAS'?{for:290,int:290,des:290}:{for:600,int:0,des:270};p.wings={rank:40,style:'solar',visible:true};p.aura={rank:40,style:'solar',visible:true};p.sliceKills=0;p.sliceWon=false;p.bar=[0,1,2,4];p.energy=100;p.resource=100;
 if(CONTENT)for(const src of CONTENT.items.filter(i=>i.class_id===p.classId&&i.level_min===175)){const it=convertItem(src);if(p.equipped[it.slot]&&p.bag.some(i=>i.sourceId===src.id))continue;p.bag.push(it);p.equipped[it.slot]=it.id;it.enchant=it.slot==='weapon'?15:5;}
 p.hp=stats(p).hp;p.mp=stats(p).mp;
 try{const old=localStorage.getItem('elyndra-lab-04');if(old)localStorage.setItem('elyndra-lab-before-visual08',old);}catch{}
 start(p);S.target=S.enemies[0];S.lastCombat=S.time-20;toast('Nova arte: sete classes +15. Mova pelo joystick. Ataque ao tocar ou segurar; use as3skills.');
}
$('visualStart').onclick=()=>{showModal('Escolha sua classe','ÁREA GRÁFICA · SET +15 · NÍVEL175',`<div class="graphicClassGrid">${Object.entries(CLASSES).map(([id,c])=>`<button data-graphic-class="${id}"><span class="graphicClassArt" style="--cx:${[0,1,2,3,0,1,2][Object.keys(CLASSES).indexOf(id)]};--cy:${Object.keys(CLASSES).indexOf(id)>3?1:0}"></span><b>${c.name}</b><small>${c.role}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-graphic-class]').forEach(b=>b.onclick=()=>{selectedClass=b.dataset.graphicClass;closeModal();startVisualGarden();});};
$('questPanel').addEventListener('click',e=>{if(!S.player?.visualSlice||e.target.closest('#questToggle'))return;e.stopImmediatePropagation();const target=S.enemies.find(v=>v.hp>0&&v.gardenBoss)||S.enemies.find(v=>v.hp>0);if(target){S.target=target;S.nav=true;S.goal={x:target.x-1.8,y:target.y};toast('Caminhando até o alvo. O ataque continua manual.');}},true);

async function enterElyndra(){const button=$('enterButton');button.disabled=true;button.textContent='PREPARANDO PERSONAGEM…';await Promise.all([visualAssetsReady,contentReady]);button.disabled=false;button.textContent='ENTRAR EM ELYNDRA';if(!CONTENT){toast('Não foi possível carregar o catálogo. Recarregue.');return;}if(saved)localStorage.setItem('elyndra-profile-backup-'+Date.now(),JSON.stringify(saved));const p=createPlayer(selectedClass,$('nameInput').value);if(GM_BUILD)provisionGM(p,CONTENT);p.region=0;p.x=12;p.y=15;start(p);p.hp=stats(p).hp;p.mp=stats(p).mp;save();closeModal();}
function gmPanel(){const p=S.player;showModal('Console do criador','GM LOCAL · RECURSOS REPOSTOS AUTOMATICAMENTE',`<div class="gmSummary"><b>NV250 · ULTRA+25 · 3SLOTS · SKILLS20</b><p>Gold e cash de teste:999.999.999. Materiais, cristais e runas são repostos. Todos os companheiros, asas, aura e Magículas começam no100. Este perfil atua apenas neste navegador; não autentica um administrador de servidor.</p></div><div class="evolutionCards"><button id="gmCharacters">MEUS PERSONAGENS</button><button id="gmFull">RESTAURAR BUILD COMPLETA</button><button id="gmProgression">PREPARAR TESTE DE EVOLUÇÃO</button><button id="gmCooldowns">ZERAR RECARGAS / HP / MP</button><button id="gmArena">ALVO DE TREINO</button></div><p class="notice">Teste de evolução reduz relíquias, Magículas e skills ao1 e encantamento ao0 para testar os botões; recursos continuam livres. Restaurar build retorna ao máximo.</p>`);$('gmCharacters').onclick=gmCharacters;$('gmFull').onclick=()=>{provisionGM(p,CONTENT,true);p.hp=stats(p).hp;p.mp=stats(p).mp;save();gmPanel();toast('Build perfeita restaurada.');};$('gmProgression').onclick=()=>{S.lastCombat=-100;p.wings.rank=p.aura.rank=p.magicula.rank=1;p.skillRanks={};for(const i of p.bag)if(Object.values(p.equipped).includes(i.id))i.enchant=0;p.hp=stats(p).hp;p.mp=stats(p).mp;save();evolutionHub();};$('gmCooldowns').onclick=()=>{S.lastCombat=-100;S.attack=false;S.pendingHits=[];S.combatEpoch=(S.combatEpoch||0)+1;S.skillCD={};S.cd={s1:0,s2:0,def:0,hp:0,mp:0,basic:0};S.cast=null;S.actionLock=0;p.hp=stats(p).hp;p.mp=stats(p).mp;p.energy=100;closeModal();toast('Combate restaurado.');};$('gmArena').onclick=skillArena;}

function gmCharacters(){save();let roster=[];try{roster=JSON.parse(localStorage.getItem('elyndra-gm-characters')||'[]');}catch{}showModal('Personagens do criador','ATÉ14PERSONAGENS · SALVOS NESTE NAVEGADOR',`<div class="gmRoster">${roster.filter(p=>CLASSES[p.classId]).map((p,i)=>`<button data-gm-character="${i}" class="gmCharacter"><b>${safe(p.name)}</b><span>${CLASSES[p.classId].name} · Nv${p.level}</span><small>${p.heroId===S.player.heroId?'ATUAL':'ENTRAR'}</small></button>`).join('')}</div><button class="primary" id="gmNewCharacter">CRIAR NOVO PERSONAGEM FULL</button>`);document.querySelectorAll('[data-gm-character]').forEach(b=>b.onclick=()=>{const p=roster[Number(b.dataset.gmCharacter)];closeModal();start(structuredClone(p));});$('gmNewCharacter').onclick=()=>{closeModal();$('hud').hidden=true;openCreation();};}

function craftCashDialog(src){const p=S.player,q=premiumCraftQuote(p,src);if(!q.ok){toast(q.reason);return;}showModal('Fabricar com cash',src.name,`<div class="premiumConfirm"><strong>${q.price.toLocaleString('pt-BR')} CASH</strong><p>${q.summary}</p><p>${q.lines.filter(l=>l.missing).map(l=>safe(l.key)+' ×'+l.missing+' · '+l.price+'cash').join('<br>')||'Você possui todos os materiais.'}</p></div><button class="primary" id="confirmCashCraft" ${p.wallet.cash<q.price?'disabled':''}>CONFIRMAR E FABRICAR</button><button class="textlink" id="backCashCraft">← Voltar</button>`);$('backCashCraft').onclick=()=>forgePanel('craft');$('confirmCashCraft').onclick=()=>{const out=premiumCraftApply(p,src,isCombat());if(!out.ok){toast(out.reason);return;}save();detail(out.item.id);toast('Peça fabricada. Atributos sorteados pelas regras normais.');};}
function purchaseInline(id,back){const p=S.player,product=CASH_PRODUCTS.find(v=>v.id===id);showModal(product.kind==='appearance'?'Adquirir aparência':'Comprar material',product.name,`<p>${product.description}</p><p>${product.price}cash · saldo${p.wallet.cash}</p><button class="primary" id="confirmInlinePurchase">COMPRAR E APLICAR</button><button class="textlink" id="cancelInlinePurchase">Voltar</button>`);$('cancelInlinePurchase').onclick=back;$('confirmInlinePurchase').onclick=()=>{const out=buyCashProduct(p,id);if(!out.ok){toast(out.reason);return;}save();back();};}

