function companionArt(d,extra='',rank=null){const actualRank=rank??S.player?.companions?.owned?.[d.id]?.rank??1,form=d.kind==='pet'?petForm(d.id,actualRank):null;return form?`<span class="companionArt petFormArt ${extra}" style="--fx:${form.stage};--fy:${form.row}" role="img" aria-label="${d.name} · ${form.name} · nível${actualRank}"></span>`:`<span class="companionArt ${extra}" style="--cx:${d.cell%3};--cy:${Math.floor(d.cell/3)}" role="img" aria-label="${d.name}"></span>`;}
function growthPanel(kind='magicula',id=null){const p=S.player;initCompanions(p);const isMagic=kind==='magicula',defs=COMPANIONS.filter(d=>d.kind===kind),selected=isMagic?null:defs.find(d=>d.id===(id||p.companions[kind]))||defs[0],owned=isMagic?p.magicula:p.companions.owned[selected.id],rank=owned?.rank||0,q=growthQuote(p,kind,selected?.id),cost=growthCost(p,kind,selected?.id),current=stats(p),preview=structuredClone(p);if(isMagic)preview.magicula.rank=Math.min(100,rank+1);else if(owned)preview.companions.owned[selected.id].rank=Math.min(100,rank+1);const next=stats(preview),delta=next.pc-current.pc,title=isMagic?'Núcleo de Magículas':kind==='pet'?'Santuário dos Companheiros':'Estábulo Astral';
showModal(title,'PODER '+current.pc.toLocaleString('pt-BR')+' · CASH '+p.wallet.cash.toLocaleString('pt-BR'),growthMarkup({kind,isMagic,defs:defs.map(d=>({...d,owned:!!p.companions.owned[d.id],rank:p.companions.owned[d.id]?.rank||0})),selected:selected?{...selected,equipped:p.companions[kind]===selected.id}:null,owned,rank,q,cost,current:{...current,gold:p.gold,material:p.materials[cost.material]||0},next,delta,art:companionArt,bonuses:isMagic?'Ataque +'+(rank*.15).toFixed(2)+'% · HP +'+(rank*.1).toFixed(2)+'% · Penetração +'+rank*2+' · Mitigação PvE '+(rank*.05).toFixed(2)+'%':companionBonusText(selected.id,rank||1),energy:magiculaAmount(current.pc,rank),testMode:p.testMode,catalog:id==='catalog'}));
$('modal').querySelector('.modal').dataset.panel='growth';
document.querySelectorAll('[data-growth-tab]').forEach(b=>b.onclick=()=>growthPanel(b.dataset.growthTab));document.querySelectorAll('[data-companion-select]').forEach(b=>b.onclick=()=>growthPanel(kind,b.dataset.companionSelect));
if(id==='catalog'){if($('growthCatalog'))$('growthCatalog').onclick=()=>growthPanel(kind);return;}const refresh=()=>growthPanel(kind,selected?.id);if($('applyMagicLab'))$('applyMagicLab').onclick=()=>{const rank=Number($('magicLabRank').value);if(isMagic)p.magicula.rank=rank;else p.companions.owned[selected.id].rank=rank;const st=stats(p);p.hp=Math.min(p.hp,st.hp);p.mp=Math.min(p.mp,st.mp);save();refresh();toast('LAB: evolução'+rank+' aplicada ao personagem.');};if($('growthCatalog'))$('growthCatalog').onclick=()=>growthPanel(kind,id==='catalog'?null:'catalog');if(owned){$('growWithMaterials').onclick=()=>{if(isCombat()){toast('Saia de combate para evoluir.');return;}const before=stats(p).pc,out=growCompanion(p,kind,selected?.id);if(!out.ok){if(q.ok)confirmGrowthCash(kind,selected?.id,refresh);else toast(out.reason);return;}save();refresh();announce('EVOLUÇÃO '+out.rank+' · +'+(stats(p).pc-before).toLocaleString('pt-BR')+' PODER');};$('growWithCash').onclick=()=>confirmGrowthCash(kind,selected?.id,refresh);if(!isMagic){$('equipCompanion').onclick=()=>{if(isCombat()){toast('Saia de combate para trocar companheiros.');return;}equipCompanion(p,kind,p.companions[kind]===selected.id?null:selected.id);save();refresh();};if($('toggleMountPanel'))$('toggleMountPanel').onclick=()=>{const out=toggleMount(p,isCombat());if(!out.ok){toast(out.reason);return;}save();refresh();};}}else for(const currency of ['Gold','Cash'])$('unlock'+currency).onclick=()=>confirmCompanionPurchase(selected.id,currency.toLowerCase(),refresh);
}
function confirmGrowthCash(kind,id,back){const p=S.player,q=growthQuote(p,kind,id);if(!q.ok){toast(q.reason);return;}showModal('Evoluir com cash','COMPRA DOS MATERIAIS FALTANTES',`<div class="premiumConfirm"><strong>${q.price.toLocaleString('pt-BR')} CASH</strong><p>${q.missing} ${q.cost.material} · ${q.gold.toLocaleString('pt-BR')}ouro faltante +150cash de aplicação.</p><p>Evolução garantida para${q.cost.rank}/100. Saldo${p.wallet.cash.toLocaleString('pt-BR')}cash.</p></div><button class="primary" id="confirmSystemCash">CONFIRMAR E EVOLUIR</button><button class="textlink" id="backSystemCash">Voltar</button>`);$('backSystemCash').onclick=back;$('confirmSystemCash').onclick=()=>{if(isCombat()){toast('Saia de combate.');return;}const before=stats(p).pc,out=growCompanion(p,kind,id,'cash');if(!out.ok){toast(out.reason);return;}save();back();toast('Evolução'+out.rank+' · +'+(stats(p).pc-before).toLocaleString('pt-BR')+'poder.');};}
function confirmCompanionPurchase(id,currency,back){const p=S.player,d=COMPANIONS.find(v=>v.id===id);showModal('Adquirir companheiro',d.name,`${companionArt(d,'purchaseArt')}<p>${d.description}</p><p>${d[currency].toLocaleString('pt-BR')} ${currency} · nível mínimo${d.minLevel}. Equipado automaticamente ao adquirir.</p><button class="primary" id="confirmCompanionBuy">CONFIRMAR AQUISIÇÃO</button><button class="textlink" id="cancelCompanionBuy">Voltar</button>`);$('cancelCompanionBuy').onclick=back;$('confirmCompanionBuy').onclick=()=>{if(isCombat()){toast('Saia de combate.');return;}const out=unlockCompanion(p,id,currency);if(!out.ok){toast(out.reason);return;}save();back();toast(d.name+' adquirido e equipado.');};}
function newCashShop(category='featured'){const p=S.player;initCompanions(p);const cats=[['featured','Destaques'],['supplies','Materiais'],['appearance','Asas & aura'],['pet','Pets'],['mount','Montarias'],['services','Serviços']];let items='';if(['pet','mount','featured'].includes(category)){items+=COMPANIONS.filter(d=>category==='featured'?['slime','wolf'].includes(d.id):d.kind===category).map(d=>`<article class="shopCard">${companionArt(d)}<div><small>${d.kind==='pet'?'COMPANHEIRO':'MONTARIA'} · NV${d.minLevel}+</small><h3>${d.name}</h3><p>${d.description}</p><button class="smallbtn" data-shop-companion="${d.id}">${p.companions.owned[d.id]?'GERENCIAR':d.cash.toLocaleString('pt-BR')+' CASH'}</button></div></article>`).join('');}if(['appearance','supplies','featured'].includes(category)){items+=CASH_PRODUCTS.filter(d=>category==='appearance'?d.kind==='appearance':category==='supplies'?d.kind==='material':['w-carmim','a-carmim','extensor'].includes(d.id)).map(d=>`<article class="shopCard"><span class="shopRelicArt ${d.kind==='appearance'?'appearanceArt':'materialArt'}" style="--style-color:${STYLES[d.style]?.color||'#00ffff'}"></span><div><small>${d.kind==='appearance'?'APARÊNCIA COM BÔNUS':'SUPRIMENTO'}</small><h3>${d.name}</h3><p>${d.description}</p><button class="smallbtn" data-store-product="${d.id}">${p.appearances.includes(d.id)?'EQUIPAR':d.price.toLocaleString('pt-BR')+' CASH'}</button></div></article>`).join('');}if(category==='supplies')items+=SUPPLIES.map(d=>`<article class="shopCard"><span class="shopRelicArt materialArt"></span><div><h3>${d.name}</h3><p>Crédito no inventário. Use na ferramenta de evolução.</p><button class="smallbtn" data-store-supply="${d.id}">${d.price.toLocaleString('pt-BR')} CASH</button></div></article>`).join('');if(category==='services')items=`<div class="serviceGrid">${[['wings','Asas'],['aura','Aura'],['magicula','Magículas'],['pet','Pets'],['mount','Montarias'],['gear','Equipamentos']].map(([k,n])=>`<button data-store-service="${k}"><b>${n}</b><small>Ver evolução e preço antes de confirmar</small></button>`).join('')}</div>`;
showModal('Empório Astral','CASH '+p.wallet.cash.toLocaleString('pt-BR')+' · OURO '+p.gold.toLocaleString('pt-BR'),`<div class="storeNav">${cats.map(([k,n])=>`<button data-store-category="${k}" class="${category===k?'selected':''}">${n}</button>`).join('')}</div><div class="shopBanner"><strong>Forje sua presença</strong><span>Compra única de companheiros · materiais em pacotes · evolução na própria ferramenta</span></div><div class="shopGrid">${items}</div><p class="storeFoot">Cash e ouro são separados. Recarga com dinheiro real ainda indisponível.${p.testMode?' <button id="storeTestCredit" class="textlink">LAB: +100.000 cash</button>':''}</p>`);document.querySelectorAll('[data-store-category]').forEach(b=>b.onclick=()=>newCashShop(b.dataset.storeCategory));document.querySelectorAll('[data-shop-companion]').forEach(b=>b.onclick=()=>{const d=COMPANIONS.find(v=>v.id===b.dataset.shopCompanion);if(p.companions.owned[d.id])growthPanel(d.kind,d.id);else confirmCompanionPurchase(d.id,'cash',()=>newCashShop(category));});document.querySelectorAll('[data-store-product]').forEach(b=>b.onclick=()=>{const d=CASH_PRODUCTS.find(v=>v.id===b.dataset.storeProduct);if(d.kind==='appearance'&&p.appearances.includes(d.id)){p[d.target].style=d.style;save();ascensionPanel(d.target);return;}purchaseInline(d.id,()=>newCashShop(category));});document.querySelectorAll('[data-store-supply]').forEach(b=>b.onclick=()=>{const d=SUPPLIES.find(v=>v.id===b.dataset.storeSupply);showModal('Comprar suprimento',d.name,`<p>${d.price}cash. Saldo${p.wallet.cash}cash.</p><button class="primary" id="confirmSupply">CONFIRMAR COMPRA</button>`);$('confirmSupply').onclick=()=>{const out=buySupply(p,d.id);if(!out.ok){toast(out.reason);return;}save();newCashShop(category);};});document.querySelectorAll('[data-store-service]').forEach(b=>b.onclick=()=>{const k=b.dataset.storeService;if(k==='gear')inventory();else if(k==='wings'||k==='aura')ascensionPanel(k);else growthPanel(k);});if($('storeTestCredit'))$('storeTestCredit').onclick=()=>{p.wallet.cash+=100000;save();newCashShop(category);};}

$('companionQuick').onclick=()=>growthPanel('pet');$('mountQuick').onclick=()=>{const out=toggleMount(S.player,isCombat());if(!out.ok){toast(out.reason);growthPanel('mount');return;}save();toast(out.mounted?'Montaria ativa. Atacar desmonta automaticamente.':'Você desmontou.');};

function interactNpc(role){if(role===1)forgePanel();else if(role===2)newCashShop();else if(role===3)growthPanel('pet');else talk();}

function companionBonusText(id,r){const pct=n=>(n*100).toFixed(2)+'%';if(id==='slime')return 'Ataque +'+pct(.01+r*.0006)+' · MP +'+pct(.02+r*.001);if(id==='fox')return 'Dano crítico +'+pct(.01+r*.0006)+' · Precisão +'+(20+r*3);if(id==='drake')return 'Ampliação espada/magia +'+pct(.01+r*.0006);if(id==='wolf')return 'HP +'+pct(.02+r*.0008)+' · DEF +'+pct(.01+r*.0006);if(id==='panther')return 'Penetração +'+(10+r)+' · Precisão +'+(30+r*3);return 'HP +'+pct(.02+r*.0008)+' · MP +'+pct(.04+r*.0016);}

function combatNumbers(){const p=S.player,st=stats(p),index=p.classId==='LAS'?6:0,changes=sensitivity(st,p.classId,index),kit=KITS[p.classId];showModal('Análise de combate',CLASS_ROLES[p.classId].label.toUpperCase(),`<p class="notice">Usa as mesmas fórmulas do combate. Valores esperados incluem chance de acerto e crítico; não são dano garantido. O PvP abaixo é simulado, sem jogadores conectados e sem dar vitórias no ranking.</p><h3>${CLASSES[p.classId].name} · ${st.pc.toLocaleString('pt-BR')} poder</h3><p>${CLASS_ROLES[p.classId].recommended}</p><h3>Impacto médio contra defesa 3.000</h3><div class="stats">${[['Ataque básico',null,1],...kit.map((k,i)=>[k.name,i,k.coef]).filter(k=>k[2]>0)].map(([name,i,coef])=>`<div class="stat">${name}<b>${Math.round(resolveStrike(st,p.classId,{def:3000,level:250},{index:i,coefficient:coef,expected:true}).value).toLocaleString('pt-BR')}</b></div>`).join('')}</div><h3>Sensibilidade · ${kit[index].name}</h3><p>Comparação por impacto com +100 de atributo plano ou +10 pontos percentuais. Taxa crítica pode já estar no limite.</p><div class="stats">${Object.entries(changes).map(([k,v])=>`<div class="stat">${optName(k)}<b>+${v.gain.toFixed(1)} dano médio</b></div>`).join('')}</div><h3>Duelo estático de referência</h3><p>Mesmo conjunto de atributos para ambos os lados, trocando apenas a classe e o kit. Limite de 60s, semente42. Não modela movimento, equipamento exclusivo, combos de recurso, buffs ou decisão humana; não estabelece qual classe é melhor.</p><div class="panelTabs">${Object.entries(CLASSES).map(([id,c])=>`<button data-sim-class="${id}">${c.name}</button>`).join('')}</div><div id="duelReport" aria-live="polite">Escolha um oponente para executar o teste.</div><button class="textlink" id="backSkills">← Habilidades</button>`);document.querySelectorAll('[data-sim-class]').forEach(b=>b.onclick=()=>{const enemyId=b.dataset.simClass,out=simulateDuel({classId:p.classId,stats:st},{classId:enemyId,stats:st},{seed:42,seconds:60});$('duelReport').innerHTML=`<div class="liveGain"><small>SIMULAÇÃO · SEM RECOMPENSAS</small><b>${out.winner?CLASSES[out.winner].name+' venceu':'Sem vencedor no limite'}</b><span>${out.elapsed.toFixed(1)}s · ${out.fighters.map(f=>CLASSES[f.classId].name+': '+f.hp.toLocaleString('pt-BR')+' HP · '+f.damage.toLocaleString('pt-BR')+' dano · '+f.criticals+' críticos').join('<br>')}</span></div>`;});$('backSkills').onclick=spellbook;}

let milestoneTimer;
function showMilestone(title,detail,key='attributes',action=attributesPanel){const el=$('milestone');clearTimeout(milestoneTimer);el.querySelector('.milestoneArt').innerHTML=commandIcon(key);$('milestoneTitle').textContent=title;$('milestoneDetail').textContent=detail;el.hidden=false;$('milestoneOpen').onclick=()=>{el.hidden=true;action();};$('milestoneClose').onclick=()=>{el.hidden=true;};milestoneTimer=setTimeout(()=>{el.hidden=true;},6500);}



// Cancel Safari's second tap default without delaying pointer-driven combat.
let lastGameTouch=0;
document.addEventListener('touchend',e=>{if(document.body.dataset.playing!=='true'||e.target.closest('#modal,input,select,textarea'))return;const now=performance.now();if(now-lastGameTouch<330)e.preventDefault();lastGameTouch=now;},{passive:false});
